Algorithm Mochila
  Define lista As Vector<String> <- vector();
  lista.append("pan");
  lista.append("leche");
  lista.append("huevos");
  For Each producto In lista Do
    Write "- ", producto;
  EndFor
EndAlgorithm

Algorithm Edades
  Define edades As Dictionary<String, Integer> <- dictionary();
  edades["Ana"] <- 12;
  edades["Leo"] <- 11;
  For Each nombre, edad In edades Do
    Write nombre, ": ", edad;
  EndFor
EndAlgorithm

Algorithm Modificar
  Define lista As Vector<Integer> <- vector();
  lista.append(1);
  lista.append(2);
  For Each n In lista Do
    lista.append(n);
  EndFor
EndAlgorithm
